"""Fork events generated by installed DSH SessionStore, not handwritten schemas."""
import json
from pathlib import Path
import subprocess
import sys
import pytest

from dma.adapters.dsh.reader import DshSessionReader
from dma.adapters.dsh.adapter import DshAdapter
from dma.errors import SourceReadError
from dma.outbox import Outbox
from dma.pipeline import capture
from dma.redaction import Redactor

FIXTURE=Path(__file__).parents[1]/"fixtures/dsh/native-fork-pilot.json"
ROOT="session-preprod-root"
CHILD="session-preprod-child"
GRAND="session-preprod-grandchild"


def logs():
    data=json.loads(FIXTURE.read_text())
    return {sid:"\n".join(json.dumps(row,ensure_ascii=False) for row in [{"type":"session",**value["header"]},*value["events"]]) for sid,value in data.items()}


def reader(sid, source, ancestors):
    return DshSessionReader(None,session_log=source,ancestor_logs=ancestors,instance_id="instance:fork",session_id=sid,actor_id="dsh-test",project_ids=("project:songta",))


def take(sid, data, box, ancestors=None):
    return capture(reader(sid,data[sid],data if ancestors is None else ancestors),box,stream="dsh:"+sid,
                   convert=DshAdapter(Redactor(),workspace_id="owner:demo",instance_id="instance:fork").to_events)


@pytest.mark.parametrize("order",[(ROOT,CHILD,GRAND),(GRAND,ROOT,CHILD),(CHILD,GRAND,ROOT)])
def test_nested_fork_is_order_independent_and_idempotent(tmp_path,order):
    data=logs();box=Outbox(tmp_path/"outbox.db",workspace_id="owner:demo",instance_id="instance:fork")
    reports=[take(sid,data,box) for sid in order]
    assert box.stats()["total"]==3
    assert sum(r["inserted"] for r in reports)==3
    with box.read() as conn:events=[json.loads(row["payload_json"]) for row in conn.execute("SELECT payload_json FROM outbox")]
    assert sorted(e["source"]["native_event_id"] for e in events)==sorted([ROOT+":seq:0",CHILD+":seq:2",GRAND+":seq:4"])
    assert {e["source"]["session_id"] for e in events}=={ROOT,CHILD,GRAND}
    for sid in order:assert take(sid,data,box)["captured_events"]==0
    assert box.stats()["total"]==3


def test_missing_ancestor_retains_native_source_without_advancing_cursor(tmp_path):
    data=logs();box=Outbox(tmp_path/"outbox.db",workspace_id="owner:demo",instance_id="instance:fork")
    with pytest.raises(SourceReadError,match="ancestor"):
        take(CHILD,data,box,ancestors={})
    assert box.stats()["total"]==0 and box.cursor("dsh:"+CHILD) is None
    take(CHILD,data,box)
    assert box.stats()["total"]==2


def test_nested_missing_original_ancestor_does_not_relabel_history(tmp_path):
    data=logs();box=Outbox(tmp_path/"outbox.db",workspace_id="owner:demo",instance_id="instance:fork")
    with pytest.raises(SourceReadError):take(GRAND,data,box,ancestors={CHILD:data[CHILD]})
    assert box.stats()["total"]==0


def test_inconsistent_parent_is_not_silently_bound(tmp_path):
    data=logs();bad=data.copy();bad[ROOT]=bad[ROOT].replace("4411","9999")
    box=Outbox(tmp_path/"outbox.db",workspace_id="owner:demo",instance_id="instance:fork")
    with pytest.raises(SourceReadError,match="prefix"):
        take(CHILD,data,box,ancestors=bad)
    assert box.stats()["total"]==0 and box.cursor("dsh:"+CHILD) is None


def test_native_cli_lineage_envelope_arrives_before_parent_capture(tmp_path):
    data=logs();db=tmp_path/"outbox.db"
    command=[sys.executable,"-m","dma.integrations.dsh.capture","--workspace","owner:demo","--instance","instance:fork","--actor","dsh-test","--session",GRAND,"--outbox",str(db),"--project","project:songta","--with-lineage"]
    envelope=json.dumps({"log":data[GRAND],"ancestors":{ROOT:data[ROOT],CHILD:data[CHILD]}},ensure_ascii=False)
    result=subprocess.run(command,input=envelope,capture_output=True,text=True,timeout=20)
    assert result.returncode==0,result.stdout+result.stderr
    assert json.loads(result.stdout)["capture"]["inserted"]==3
    assert "4411" not in result.stdout+result.stderr
    assert Outbox(db).stats()["total"]==3
